INSERT INTO public.matans (id, title, author, category, level, slug, description, color, total_chapters) VALUES ('balaghah', 'Ilmu Ma''ani', 'Dr. Abd al-''Aziz ''Atiq', 'Balaghah', 'Pemula', 'balaghah', 'Kajian Struktur dan Makna Tuturan dalam Balaghah Arab.', 'maroon', 30) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description;
INSERT INTO public.matan_chapters (id, matan_id, title, description, order_index) VALUES (gen_random_uuid(), 'balaghah', 'BALAGHAH', 'Definisi Dasar Balaghah', 1) RETURNING id;
INSERT INTO tmp_chapters (idx, id) SELECT 1, id FROM public.matan_chapters WHERE matan_id='balaghah' AND order_index=1;
INSERT INTO public.matan_items (chapter_id, bait_arabic, translation, syarah_text, quizzes, order_index) VALUES ((SELECT id FROM tmp_chapters WHERE idx=1), '', 'S Secara etimologis, kata Balaghah berasal dari ungkapan: balaghtu al-ghayah (aku telah sampai pada ...', 'S Secara etimologis, kata Balaghah berasal dari ungkapan: balaghtu al-ghayah (aku telah sampai pada tujuan) ketika engkau mencapainya, dan ballaghtuha ghairi (aku menyampaikannya kepada selainku). Adapun al-mubalaghah dalam suatu urusan berarti engkau mengerahkan segenap usahamu hingga mencapai puncaknya. Disiplin ilmu ini dinamakan Balaghah karena ia berfungsi menyampaikan makna hingga ke dalam hati pendengarnya sehingga ia dapat memahaminya. Dikatakan: balugha ar-rajulu balaghatan (seseorang telah mencapai tingkat balaghah), jika ia telah menjadi baligh (orang yang fasih dan pandai bertutur). Rajulun baligh adalah orang yang baik tutur katanya, yang mampu mengungkapkan esensi (kunh) hatinya melalui ekspresi lisannya[1]. Dikatakan pula: ablaghtu fi al-kalam (aku telah menerapkan balaghah dalam tuturan), jika engkau menghadirkan aspek balaghah di dalamnya.', '[{"question": "Secara etimologis, Balaghah (balaghtu al-ghayah) berarti...", "correct": "Aku telah sampai pada tujuan", "options": ["Aku telah mahir bahasa", "Aku telah sampai pada tujuan", "Aku telah menghafal syair", "Aku telah menulis surat"]}]'::jsonb, 1);
INSERT INTO public.matan_items (chapter_id, bait_arabic, translation, syarah_text, quizzes, order_index) VALUES ((SELECT id FROM tmp_chapters WHERE idx=1), '', 'Balaghah merupakan sifat bagi tuturan (kalam), bukan sifat bagi penutur (mutakallim)....', 'Balaghah merupakan sifat bagi tuturan (kalam), bukan sifat bagi penutur (mutakallim).', '[{"question": "Balaghah pada hakikatnya merupakan sifat bagi apa?", "correct": "Kalam (tuturan)", "options": ["Mutakallim (penutur)", "Kalam (tuturan)", "Mushannif (penulis)", "Sami' (pendengar)"]}]'::jsonb, 2);
INSERT INTO public.matan_items (chapter_id, bait_arabic, translation, syarah_text, quizzes, order_index) VALUES ((SELECT id FROM tmp_chapters WHERE idx=1), '', 'Penyebutan seorang penutur sebagai baligh adalah bentuk perluasan makna (tawassu’)....', 'Penyebutan seorang penutur sebagai baligh adalah bentuk perluasan makna (tawassu’).', '[{"question": "Penyebutan seorang penutur sebagai 'baligh' sebenarnya adalah...", "correct": "Perluasan makna (tawassu\u2019)", "options": ["Makna hakiki", "Perluasan makna (tawassu\u2019)", "Kesalahan istilah", "Kiasan jauh"]}]'::jsonb, 3);
INSERT INTO public.matan_items (chapter_id, bait_arabic, translation, syarah_text, quizzes, order_index) VALUES ((SELECT id FROM tmp_chapters WHERE idx=1), '', 'Hakikatnya adalah tuturannya yang bersifat baligh, di mana objek yang disifati (maushuf) dihilangkan...', 'Hakikatnya adalah tuturannya yang bersifat baligh, di mana objek yang disifati (maushuf) dihilangkan dan sifatnya (shifah) menggantikan posisinya. Sebagaimana engkau berkata:', '[{"question": "Dalam struktur kalimat baligh, apa yang biasanya digantikan posisinya oleh sifat?", "correct": "Maushuf (objek yang disifati)", "options": ["Fi'il (kata kerja)", "Maushuf (objek yang disifati)", "Fa'il (pelaku)", "Harf (kata sambung)"]}]'::jsonb, 4);
INSERT INTO public.matan_items (chapter_id, bait_arabic, translation, syarah_text, quizzes, order_index) VALUES ((SELECT id FROM tmp_chapters WHERE idx=1), '', 'fulanun rajulun muhkam (Fulan adalah orang yang terukur), yang engkau maksud adalah perbuatannya yan...', 'fulanun rajulun muhkam (Fulan adalah orang yang terukur), yang engkau maksud adalah perbuatannya yang terukur. Allah Swt. berfirman: “hikmatun balighah” (suatu hikmah yang sempurna) [QS. Al-Qamar: 5], di mana Allah menjadikan balaghah sebagai sifat bagi hikmah, bukan bagi Sang Pemilik hikmah. Namun, frekuensi penggunaan yang tinggi menjadikan penyebutan penutur sebagai baligh seolah-olah menjadi makna hakiki.', '[{"question": "Dalam ayat 'hikmatun balighah', Balaghah menjadi sifat bagi apa?", "correct": "Hikmah itu sendiri", "options": ["Pembawa hikmah", "Hikmah itu sendiri", "Pendengar hikmah", "Penulis hikmah"]}]'::jsonb, 5);
INSERT INTO public.matan_items (chapter_id, bait_arabic, translation, syarah_text, quizzes, order_index) VALUES ((SELECT id FROM tmp_chapters WHERE idx=1), '', 'Sebagaimana frekuensi penggunaan yang tinggi juga menjadikan penyebutan sebuah kata seperti al-muzad...', 'Sebagaimana frekuensi penggunaan yang tinggi juga menjadikan penyebutan sebuah kata seperti al-muzadah[2] sebagai rawiyah seolah-olah makna hakiki, padahal pada asalnya ar-rawiyah adalah pembawa al-muzadah, yaitu unta atau sejenisnya. Atas dasar inilah, pembawa (penghafal) syair disebut rawiyah.', '[{"question": "Mengapa penghafal syair disebut 'rawiyah' secara metaforis?", "correct": "Karena disamakan dengan unta pembawa air (rawiyah)", "options": ["Karena suaranya bagus", "Karena disamakan dengan unta pembawa air (rawiyah)", "Karena tulisannya indah", "Karena ia sangat pintar"]}]'::jsonb, 6);
INSERT INTO public.matan_items (chapter_id, bait_arabic, translation, syarah_text, quizzes, order_index) VALUES ((SELECT id FROM tmp_chapters WHERE idx=1), '', 'Demikianlah pengertian Balaghah secara etimologis. Sejak dahulu, para ulama telah berbeda pendapat d...', 'Demikianlah pengertian Balaghah secara etimologis. Sejak dahulu, para ulama telah berbeda pendapat dalam mendefinisikan dan mendeskripsikannya secara terminologis.', '[{"question": "Selain definisi etimologis, para ulama merumuskan Balaghah secara...", "correct": "Terminologis (ishthilahan)", "options": ["Filosofis", "Terminologis (ishthilahan)", "Sosiologis", "Historis"]}]'::jsonb, 7);
INSERT INTO public.matan_items (chapter_id, bait_arabic, translation, syarah_text, quizzes, order_index) VALUES ((SELECT id FROM tmp_chapters WHERE idx=1), '', 'Ibn Rasyiq al-Qayrawani dalam kitabnya, al-‘Umdah[3], telah menyajikan serangkaian definisi dari par...', 'Ibn Rasyiq al-Qayrawani dalam kitabnya, al-‘Umdah[3], telah menyajikan serangkaian definisi dari para ahli balaghah (bulagha’) dalam merumuskan konsep Balaghah sebagaimana 1 Terkadang, istilah al-qalb (hati) digunakan untuk mengungkapkan makna al-‘aql (akal). Allah Swt. berfirman:', '[{"question": "Siapa tokoh yang menyajikan serangkaian definisi Balaghah dalam kitab al-\u2018Umdah?", "correct": "Ibn Rasyiq al-Qayrawani", "options": ["Al-Jahiz", "Ibn Rasyiq al-Qayrawani", "Sibawayh", "Al-Jurjani"]}]'::jsonb, 8);
INSERT INTO public.matan_items (chapter_id, bait_arabic, translation, syarah_text, quizzes, order_index) VALUES ((SELECT id FROM tmp_chapters WHERE idx=1), '', '«Sesungguhnya pada yang demikian itu benar-benar terdapat peringatan bagi orang-orang yang mempunyai...', '«Sesungguhnya pada yang demikian itu benar-benar terdapat peringatan bagi orang-orang yang mempunyai hati (akal)...» (QS. Qaf: 37).', '[{"question": "Di QS. Qaf: 37, istilah 'hati' ditafsirkan sebagai apa?", "correct": "Akal (al-'aql)", "options": ["Perasaan", "Akal (al-'aql)", "Nyawa", "Keinginan"]}]'::jsonb, 9);
INSERT INTO public.matan_items (chapter_id, bait_arabic, translation, syarah_text, quizzes, order_index) VALUES ((SELECT id FROM tmp_chapters WHERE idx=1), '', '2 Al-Muzadah: geriba atau kantong kulit yang digunakan untuk membawa air....', '2 Al-Muzadah: geriba atau kantong kulit yang digunakan untuk membawa air.', '[{"question": "Apa arti dari istilah teknis 'al-muzadah'?", "correct": "Kantong air dari kulit", "options": ["Pedang tajam", "Kantong air dari kulit", "Tenda padang pasir", "Pelana kuda"]}]'::jsonb, 10);
INSERT INTO public.matan_items (chapter_id, bait_arabic, translation, syarah_text, quizzes, order_index) VALUES ((SELECT id FROM tmp_chapters WHERE idx=1), '', '3 Kitab al-‘Umdah, Jil. 1, hlm. 213. Ibn Rasyiq adalah Abu ‘Ali al-Hasan bin Rasyiq al-Azdi al-Qayra...', '3 Kitab al-‘Umdah, Jil. 1, hlm. 213. Ibn Rasyiq adalah Abu ‘Ali al-Hasan bin Rasyiq al-Azdi al-Qayrawani (w. 385-465 H).', '[{"question": "Ibn Rasyiq al-Qayrawani adalah ulama yang wafat pada abad ke-...", "correct": "5 Hijriah (465 H)", "options": ["3 Hijriah", "5 Hijriah (465 H)", "7 Hijriah", "2 Hijriah"]}]'::jsonb, 11);
INSERT INTO public.matan_items (chapter_id, bait_arabic, translation, syarah_text, quizzes, order_index) VALUES ((SELECT id FROM tmp_chapters WHERE idx=1), '', 'yang tergambar oleh para penutur defi nisi tersebut. Meskipun demikian, menelaah setiap defi nisi in...', 'yang tergambar oleh para penutur defi nisi tersebut. Meskipun demikian, menelaah setiap defi nisi ini secara terpisah tidak memberikan kita sebuah konsep yang komprehensif dan eksklusif (jami’ mani’) untuk Balaghah. Namun, barangkali konsep Balaghah yang dicari dapat dirumuskan dari celah-celah sebagian defi nisi berikut. Mari kita coba menelaahnya.', '[{"question": "Mengapa menelaah satu definisi Balaghah saja dianggap belum cukup?", "correct": "Karena belum mencakup konsep secara komprehensif (jami' mani')", "options": ["Karena bahasanya terlalu sulit", "Karena belum mencakup konsep secara komprehensif (jami' mani')", "Karena definisinya bertentangan", "Karena tidak ada contohnya"]}]'::jsonb, 12);
INSERT INTO public.matan_items (chapter_id, bait_arabic, translation, syarah_text, quizzes, order_index) VALUES ((SELECT id FROM tmp_chapters WHERE idx=1), '', 'Sebagian ahli balaghah ditanya: “Apakah Balaghah itu?” Ia menjawab: “(Tuturan) yang sedikit (kata) d...', 'Sebagian ahli balaghah ditanya: “Apakah Balaghah itu?” Ia menjawab: “(Tuturan) yang sedikit (kata) dapat dipahami dan yang banyak (kata) tidak membosankan.” Yang lain ditanya, lalu menjawab: “Makna yang banyak dalam lafal yang sedikit.” Seseorang ditanya: “Apakah Balaghah itu?” Ia menjawab: “Ketepatan makna dan keindahan peringkasan (ijaz).” Sebagian orang Arab Badui ditanya: “Siapakah orang yang paling baligh?” Ia menjawab:', '[{"question": "Menurut salah satu ahli, Balaghah adalah makna yang banyak dalam...", "correct": "Lafal yang sedikit", "options": ["Buku yang tebal", "Lafal yang sedikit", "Suara yang keras", "Tulisan yang indah"]}]'::jsonb, 13);
INSERT INTO public.matan_items (chapter_id, bait_arabic, translation, syarah_text, quizzes, order_index) VALUES ((SELECT id FROM tmp_chapters WHERE idx=1), '', '“Yang paling mudah lafalnya dan paling baik improvisasinya (badihah).” Khalaf al-Ahmar berkata: “Bal...', '“Yang paling mudah lafalnya dan paling baik improvisasinya (badihah).” Khalaf al-Ahmar berkata: “Balaghah adalah isyarat yang ekspresif.” Al-Khalil bin Ahmad berkata: “Balaghah adalah satu kata yang menyingkap maknamakna selanjutnya.” Al-Mufadhdhal al-Dhabbi berkata: Aku bertanya kepada seorang Arab Badui:', '[{"question": "Khalaf al-Ahmar mendefinisikan Balaghah sebagai...", "correct": "Isyarat yang ekspresif", "options": ["Penjelasan yang panjang", "Isyarat yang ekspresif", "Puisi yang berima", "Dialog yang jujur"]}]'::jsonb, 14);
INSERT INTO public.matan_items (chapter_id, bait_arabic, translation, syarah_text, quizzes, order_index) VALUES ((SELECT id FROM tmp_chapters WHERE idx=1), '', '“Menurut kalian, apakah Balaghah itu?” Ia menjawab: “Peringkasan (ijaz) tanpa menimbulkan kekurangan...', '“Menurut kalian, apakah Balaghah itu?” Ia menjawab: “Peringkasan (ijaz) tanpa menimbulkan kekurangan (makna), dan pemaparan panjang (ithnab) tanpa bertele-tele.” Ja’far bin Yahya bin Khalid al-Barmaki menulis surat kepada ‘Amr bin Mas’adah: “Jika pemaparan panjang (al-iktsar) lebih efektif, maka peringkasan (al-ijaz) adalah sebuah kelalaian. Namun, jika peringkasan sudah mencukupi, maka pemaparan panjang adalah sebuah kelemahan (‘iyy).” Seseorang ditanya: “Apakah Balaghah itu?” Ia menjawab: “Tersampaikannya hajat seorang penutur melalui pemahaman yang baik dari sisi pendengar. Karena itulah ia dinamakan balaghah.” Yang lain berkata: “Balaghah adalah pengetahuan tentang pemisahan (fashl) dan penyambungan (washl) kalimat.” Dikatakan pula: “Balaghah adalah keindahan ungkapan disertai kebenaran penunjukan makna (dalalah).” Dikatakan pula: “Balaghah adalah kekuatan dalam penjelasan (bayan) disertai keindahan struktur (nizham).” Mereka berkata: “Balaghah adalah lawan dari al-‘iyy (kelemahan berbahasa), dan al-‘iyy adalah ketidakmampuan untuk menjelaskan.” Aristoteles ditanya: “Apakah Balaghah itu?” Ia menjawab: “Keindahan penggunaan metafora (isti’arah).” Khalid bin Shafwan ditanya: “Apakah Balaghah itu?” Ia menjawab: “Ketepatan makna dan kesengajaan untuk menuju pada argumen (hujjah).” Ibrahim al-Imam ditanya: “Apakah Balaghah itu?” Ia menjawab: “Kejelasan lafal (jazalah) dan pemaparan yang panjang (ithalah).” Al-Buhturi berkata saat memuji Muhammad bin ‘Abd al-Malik bin al-Zayyat ketika Balaghah diangkat menjadi wazir dan menyifati balaghah-nya:', '[{"question": "Siapa filsuf klasik yang mengaitkan Balaghah dengan keindahan metafora (isti\u2019arah)?", "correct": "Aristoteles", "options": ["Plato", "Aristoteles", "Socrates", "Epicurus"]}]'::jsonb, 15);
INSERT INTO public.matan_items (chapter_id, bait_arabic, translation, syarah_text, quizzes, order_index) VALUES ((SELECT id FROM tmp_chapters WHERE idx=1), 'و', 'ﻣﻌان لو فﺼلتها القــــــوافﻲ • ﻫجﻨﺖ شﻌر ﺟــــــــــرول ولبيد > ﺣــــﺰن ﻣﺴتﻌمل الﻜلام اﺧتيارا • وتجﻨي...', 'ﻣﻌان لو فﺼلتها القــــــوافﻲ • ﻫجﻨﺖ شﻌر ﺟــــــــــرول ولبيد
INSERT INTO public.matan_items (chapter_id, bait_arabic, translation, syarah_text, quizzes, order_index) VALUES ((SELECT id FROM tmp_chapters WHERE idx=1), '', 'Makna-makna itu sulit (dicapai), (namun) memilih menggunakan tuturan yang lazim, serta menghindari k...', 'Makna-makna itu sulit (dicapai), (namun) memilih menggunakan tuturan yang lazim, serta menghindari kegelapan kerumitan (ta’qid).', '[{"question": "Apa yang dihindari oleh seorang baligh agar maknanya tidak gelap?", "correct": "Kerumitan (ta\u2019qid)", "options": ["Kesederhanaan", "Kerumitan (ta\u2019qid)", "Kejujuran", "Keringkasan"]}]'::jsonb, 17);
INSERT INTO public.matan_items (chapter_id, bait_arabic, translation, syarah_text, quizzes, order_index) VALUES ((SELECT id FROM tmp_chapters WHERE idx=1), '', 'Mereka menggunakan lafal yang sederhana, namun dengannya berhasil meraih tujuan makna yang mendalam....', 'Mereka menggunakan lafal yang sederhana, namun dengannya berhasil meraih tujuan makna yang mendalam.', '[{"question": "Bagaimana cara seorang baligh meraih tujuan makna yang mendalam?", "correct": "Dengan menggunakan lafal yang lazim/sederhana", "options": ["Dengan kata-kata yang sangat sulit", "Dengan menggunakan lafal yang lazim/sederhana", "Dengan berteriak", "Dengan menulis sangat panjang"]}]'::jsonb, 18);
INSERT INTO public.matan_items (chapter_id, bait_arabic, translation, syarah_text, quizzes, order_index) VALUES ((SELECT id FROM tmp_chapters WHERE idx=1), '', 'Al-‘Attabi berkata: “Penegak tuturan adalah akal, perhiasannya adalah kebenaran, ornamennya adalah i...', 'Al-‘Attabi berkata: “Penegak tuturan adalah akal, perhiasannya adalah kebenaran, ornamennya adalah i’rab, penjinaknya adalah lisan, raganya adalah bakat (qarihah), dan ruhnya adalah makna.” Ibn al-Muqaffa’ ditanya: “Apakah Balaghah itu?” Ia menjawab: “Ia adalah nama untuk serangkaian makna yang berlaku dalam berbagai bentuk: di antaranya ada yang terwujud dalam diam, ada yang dalam menyimak, ada yang dalam isyarat, ada yang berbentuk syair, ada yang berbentuk sajak (saj’), ada yang berbentuk permulaan (inisiatif), ada yang berbentuk jawaban, ada yang dalam percakapan, ada yang dalam perdebatan (ihtijaj), ada yang berbentuk khotbah, dan ada yang berbentuk surat-menyurat. Inti dari semua kategori ini adalah penyampaian isyarat makna (al-wahy wa al-isyarah ila al-ma’na), dan keringkasan (al-ijaz) adalah esensi Balaghah itu sendiri.” Abu al-Hasan ‘Ali bin ‘Isa al-Rummani berkata: “Asal Balaghah adalah tabiat (thab’). Meskipun demikian, ia memiliki instrumen-instrumen yang membantu dan mengantarkan pada penguasaannya, yang juga berfungsi sebagai tolok ukur dan pembeda antara Balaghah dengan yang lainnya. Instrumen-instrumen ini ada delapan jenis: ijaz (keringkasan), isti’arah (metafora), bayan (penjelasan), nazhm (struktur), tasharruf (variasi gaya), musyakalah (penyesuaian bentuk), dan matsal (perumpamaan).” ‘Abdullah bin Muhammad bin Jamil, yang dikenal dengan al-Bahith, berkata: “Balaghah adalah pemahaman dan kemampuan membuat paham, penyingkapan makna, penguasaan i’rab, kekayaan kosakata (ittisa’ fi al-lafzh), ketepatan struktur (sadad fi an-nazhm), pengetahuan akan tujuan, kejelasan dalam penyampaian, kebenaran isyarat, kejelasan penunjukan makna, pengetahuan tentang seni bertutur, kecukupan dengan peringkasan daripada pemaparan panjang, dan keteguhan hati berdasarkan pilihan yang terbaik...', '[{"question": "Menurut Al-Rummani, ada berapa jenis instrumen pendukung Balaghah?", "correct": "Delapan jenis", "options": ["Empat jenis", "Delapan jenis", "Sepuluh jenis", "Tiga jenis"]}]'::jsonb, 19);
INSERT INTO public.matan_items (chapter_id, bait_arabic, translation, syarah_text, quizzes, order_index) VALUES ((SELECT id FROM tmp_chapters WHERE idx=1), '', 'Ia melanjutkan: Semua kategori ini saling membutuhkan satu sama lain, seperti halnya kebutuhan antar...', 'Ia melanjutkan: Semua kategori ini saling membutuhkan satu sama lain, seperti halnya kebutuhan antar anggota tubuh: keutamaan satu bagian tidak bisa terlepas dari yang lain.', '[{"question": "Kebutuhan antar kategori Balaghah diibaratkan seperti hubungan antar...", "correct": "Anggota tubuh", "options": ["Bintang di langit", "Anggota tubuh", "Bebatuan di gunung", "Air di laut"]}]'::jsonb, 20);
INSERT INTO public.matan_items (chapter_id, bait_arabic, translation, syarah_text, quizzes, order_index) VALUES ((SELECT id FROM tmp_chapters WHERE idx=1), '', 'Barang siapa menguasai semua karakteristik ini, maka ia telah mencapai kesempurnaan....', 'Barang siapa menguasai semua karakteristik ini, maka ia telah mencapai kesempurnaan.', '[{"question": "Seseorang dikatakan mencapai kesempurnaan Balaghah jika...", "correct": "Menguasai semua karakteristik instrumennya", "options": ["Memiliki suara yang lantang", "Menguasai semua karakteristik instrumennya", "Menulis banyak buku", "Menang dalam perdebatan"]}]'::jsonb, 21);
INSERT INTO public.matan_items (chapter_id, bait_arabic, translation, syarah_text, quizzes, order_index) VALUES ((SELECT id FROM tmp_chapters WHERE idx=1), '', 'Dan barang siapa kehilangan sebagiannya, maka ia tidak jauh dari kekurangan, meskipun ia memiliki se...', 'Dan barang siapa kehilangan sebagiannya, maka ia tidak jauh dari kekurangan, meskipun ia memiliki sebagian lainnya... Ia melanjutkan: Balaghah adalah pemilihan lafal dalam keindahan cara membuat paham.” Itulah serangkaian defi nisi dari para ahli balaghah dalam merumuskan konsep Balaghah 1 Maksudnya adalah penyair al-Huthay’ah.', '[{"question": "Menurut al-Bahith, Balaghah adalah pemilihan lafal dalam keindahan cara...", "correct": "Membuat paham (al-ifham)", "options": ["Bersajak", "Membuat paham (al-ifham)", "Berdebat", "Menghibur"]}]'::jsonb, 22);
INSERT INTO public.matan_items (chapter_id, bait_arabic, translation, syarah_text, quizzes, order_index) VALUES ((SELECT id FROM tmp_chapters WHERE idx=1), '', 'sebagaimana yang dipahami oleh masing-masing dari mereka. Dari defi nisi-defi nisi tersebut, konsep ...', 'sebagaimana yang dipahami oleh masing-masing dari mereka. Dari defi nisi-defi nisi tersebut, konsep Balaghah dapat dirumuskan sebagai: penempatan tuturan pada posisinya yang tepat, baik dalam bentuk panjang (thul) maupun ringkas (ijaz); penyampaian makna secara jelas dengan ungkapan yang benar (shahihah) dan fasih (fashihah) yang memiliki daya pikat (khallab) dalam jiwa; serta kesesuaian setiap tuturan dengan konteks (maqam) penyampaiannya dan lawan bicaranya.', '[{"question": "Ciri utama Balaghah adalah kesesuaian setiap tuturan dengan...", "correct": "Konteks (maqam) dan lawan bicara", "options": ["Urutan abjad", "Konteks (maqam) dan lawan bicara", "Jumlah baris", "Waktu siang/malam"]}]'::jsonb, 23);
INSERT INTO public.matan_items (chapter_id, bait_arabic, translation, syarah_text, quizzes, order_index) VALUES ((SELECT id FROM tmp_chapters WHERE idx=1), '', 'Barangkali defi nisi dari ‘Abdullah bin Muhammad bin Jamil adalah yang paling mendekati defi nisi in...', 'Barangkali defi nisi dari ‘Abdullah bin Muhammad bin Jamil adalah yang paling mendekati defi nisi ini, sebagaimana konsep Balaghah menurut Abu al-Hasan al-Rummani lebih terkait dengan dasar-dasar dan pembahasan-pembahasannya. Akan tetapi, sebelum dan sesudah semua ini, Balaghah adalah sebuah seni bertutur (fann qawli) yang bergantung pada bakat (mauhibah), kejernihan potensi, ketajaman dalam menangkap keindahan, dan kemampuan membedakan perbedaan-perbedaan subtil di antara beragam gaya bahasa (asalib). Bagi seorang penuntut ilmu Balaghah, ada dua hal yang mutlak diperlukan: (1) membaca karya-karya sastra agung secara mendalam dan berkesinambungan serta menghafal bagian-bagian yang dianggapnya indah, dan (2) berlatih dari waktu ke waktu untuk mengungkapkan apa yang terlintas dalam benak dan bergejolak dalam jiwa. Tidak diragukan lagi bahwa perpaduan kedua hal ini akan membantu dalam membentuk cita rasa sastra (dzawq adabi), mengkritik karya sastra, dan menilainya.', '[{"question": "Penuntut ilmu Balaghah wajib membaca karya sastra agung dan...", "correct": "Berlatih mengungkapkan gejolak jiwa", "options": ["Menghafal seluruh kamus", "Berlatih mengungkapkan gejolak jiwa", "Pergi ke padang pasir", "Mempelajari sejarah perang"]}]'::jsonb, 24);
INSERT INTO public.matan_items (chapter_id, bait_arabic, translation, syarah_text, quizzes, order_index) VALUES ((SELECT id FROM tmp_chapters WHERE idx=1), '', 'Dari defi nisi-defi nisi para ahli balaghah sebelumnya, kita juga dapat dengan mudah merumuskan unsu...', 'Dari defi nisi-defi nisi para ahli balaghah sebelumnya, kita juga dapat dengan mudah merumuskan unsur-unsur Balaghah. Unsur-unsur ini adalah: lafal, makna, komposisi lafallafal dengan cara yang memberikannya kekuatan dan pengaruh yang baik, serta ketepatan dalam memilih kata-kata dan gaya bahasa sesuai dengan konteks tuturan, tema-temanya, kondisi pendengar, dan kecenderungan psikologis yang menguasai mereka.', '[{"question": "Sebutkan unsur utama Balaghah yang sering dirumuskan para ahli!", "correct": "Lafal, makna, dan komposisi", "options": ["Hanya keindahan kata", "Lafal, makna, dan komposisi", "Hanya kebenaran logika", "Hanya kecepatan bicara"]}]'::jsonb, 25);
INSERT INTO public.matan_items (chapter_id, bait_arabic, translation, syarah_text, quizzes, order_index) VALUES ((SELECT id FROM tmp_chapters WHERE idx=1), '', 'Atas dasar ini, seorang baligh (penutur yang fasih) harus merenungkan makna-makna yang bergejolak da...', 'Atas dasar ini, seorang baligh (penutur yang fasih) harus merenungkan makna-makna yang bergejolak dalam dirinya, dengan syarat makna-makna tersebut haruslah jujur dan kuat, serta menampakkan jejak orisinalitas dan keutuhan cita rasa (dzawq) dalam penyusunan dan penataannya yang baik. Apabila hal ini telah tercapai, ia kemudian memilih lafal-lafal yang jelas dan berpengaruh, yang selaras dengan natur makna tersebut dan mampu mengungkapkannya dengan ekspresi yang paling agung. Meskipun demikian, patut kita ingat selalu bahwa balaghah tidak terletak pada lafal semata, tidak pula pada makna semata, melainkan pada ikatan organis di antara keduanya, serta merupakan efek yang niscaya dari keutuhan dan keharmonisan keduanya.', '[{"question": "Balaghah terletak pada 'ikatan organis' antara...", "correct": "Lafal dan makna", "options": ["Penulis dan pembaca", "Lafal dan makna", "Masa lalu dan sekarang", "Bumi dan langit"]}]'::jsonb, 26);
INSERT INTO public.matan_items (chapter_id, bait_arabic, translation, syarah_text, quizzes, order_index) VALUES ((SELECT id FROM tmp_chapters WHERE idx=1), '', 'Demikianlah tentang balaghah (sebagai konsep umum). Adapun balaghah al-kalam (retorika tuturan) adal...', 'Demikianlah tentang balaghah (sebagai konsep umum). Adapun balaghah al-kalam (retorika tuturan) adalah kesesuaian tuturan tersebut dengan tuntutan konteks (muqtadha al-hal) disertai dengan fashahah-nya. Tuntutan konteks ini bervariasi mengikuti perbedaan situasi-situasi tuturan. Misalnya, konteks penjamakan (tankir), pemutlakan (ithlaq), pendahuluan (taqdim), dan penyebutan (dzikr) berbeda dengan kebalikannya, yaitu penentuan (ta’rif), pembatasan (qashr), pengakhiran (ta’khir), dan penghilangan (hadzf).', '[{"question": "Kesesuaian tuturan dengan tuntutan konteks disebut...", "correct": "Muqtadha al-hal", "options": ["Thabaqatul lisan", "Muqtadha al-hal", "Ilmu mantiq", "Fashahatul mufrad"]}]'::jsonb, 27);
INSERT INTO public.matan_items (chapter_id, bait_arabic, translation, syarah_text, quizzes, order_index) VALUES ((SELECT id FROM tmp_chapters WHERE idx=1), '', 'Konteks pemisahan kalimat (fashl) berbeda dengan konteks penyambungan (washl), dan konteks peringkas...', 'Konteks pemisahan kalimat (fashl) berbeda dengan konteks penyambungan (washl), dan konteks peringkasan (ijaz) berbeda dengan konteks pemaparan panjang (ithnab) maupun konteks kesetaraan (musawah).', '[{"question": "Lawan dari konteks 'ijaz' (ringkas) adalah...", "correct": "Ithnab (panjang lebar)", "options": ["Syamail", "Ithnab (panjang lebar)", "I'rab", "Mubtada'"]}]'::jsonb, 28);
INSERT INTO public.matan_items (chapter_id, bait_arabic, translation, syarah_text, quizzes, order_index) VALUES ((SELECT id FROM tmp_chapters WHERE idx=1), '', 'Balaghah Meningkatnya kualitas tuturan dari segi keindahan dan penerimaannya ditentukan oleh kesesua...', 'Balaghah Meningkatnya kualitas tuturan dari segi keindahan dan penerimaannya ditentukan oleh kesesuaiannya dengan pertimbangan yang relevan (al-i’tibar al-munasib), dan menurunnya kualitas tuturan disebabkan oleh ketiadaan hal tersebut. Dengan demikian, muqtadha al-hal adalah pertimbangan yang relevan itu sendiri.', '[{"question": "Faktor keindahan tuturan ditentukan oleh 'al-i\u2019tibar al-munasib', yaitu...", "correct": "Pertimbangan yang relevan", "options": ["Gaya bahasa puitis", "Pertimbangan yang relevan", "Suara yang merdu", "Waktu yang tepat"]}]'::jsonb, 29);
INSERT INTO public.matan_items (chapter_id, bait_arabic, translation, syarah_text, quizzes, order_index) VALUES ((SELECT id FROM tmp_chapters WHERE idx=1), '', 'Balaghah memiliki dua tingkatan: tingkatan tertinggi, yaitu batas kemukjizatan (i’jaz) dan yang mend...', 'Balaghah memiliki dua tingkatan: tingkatan tertinggi, yaitu batas kemukjizatan (i’jaz) dan yang mendekatinya; dan tingkatan terendah, yaitu batas di mana jika sebuah tuturan diubah ke tingkat yang lebih rendah darinya, maka menurut para ahli balaghah, ia akan setara dengan suara hewan. Di antara kedua tingkatan ini terdapat banyak jenjang.', '[{"question": "Tingkatan tertinggi Balaghah disebut sebagai batas...", "correct": "Kemukjizatan (i\u2019jaz)", "options": ["Kefasihan biasa", "Kemukjizatan (i\u2019jaz)", "Kesederhanaan", "Keindahan fana"]}]'::jsonb, 30);
INSERT INTO public.matan_items (chapter_id, bait_arabic, translation, syarah_text, quizzes, order_index) VALUES ((SELECT id FROM tmp_chapters WHERE idx=1), '', 'Barangkali dari semua yang telah dipaparkan, kita dapat memahami bahwa balaghah merujuk pada dua hal...', 'Barangkali dari semua yang telah dipaparkan, kita dapat memahami bahwa balaghah merujuk pada dua hal: (1) kemampuan membedakan tuturan yang fashih (fasih) dari yang tidak, dan (2) kehati-hatian dari kekeliruan dalam menyampaikan makna yang dimaksud.', '[{"question": "Balaghah membantu menjaga penutur dari kekeliruan dalam...", "correct": "Menyampaikan makna yang dimaksud", "options": ["Menulis huruf hijaiyah", "Menyampaikan makna yang dimaksud", "Menghitung jumlah kata", "Mencari rima syair"]}]'::jsonb, 31);
INSERT INTO public.matan_items (chapter_id, bait_arabic, translation, syarah_text, quizzes, order_index) VALUES ((SELECT id FROM tmp_chapters WHERE idx=1), '', 'Adapun kemampuan membedakan yang fashih dari yang tidak, sebagiannya dijelaskan dalam ilmu leksikolo...', 'Adapun kemampuan membedakan yang fashih dari yang tidak, sebagiannya dijelaskan dalam ilmu leksikologi (matn al-lughah), morfologi (sharf), atau sintaksis (nahw), atau dapat dirasakan melalui intuisi kebahasaan (al-hiss). Sedangkan kehati-hatian dari kekeliruan dalam menyampaikan makna yang dimaksud dicapai melalui Ilmu Ma’ani, dengan mengecualikan aspek makna yang dijaga melalui Ilmu Bayan.', '[{"question": "Ilmu yang menjaga kehati-hatian dalam penyampaian makna adalah...", "correct": "Ilmu Ma\u2019ani", "options": ["Ilmu Arudh", "Ilmu Ma\u2019ani", "Ilmu Tajwid", "Ilmu Hadis"]}]'::jsonb, 32);
